 for line in f:
  e=json.loads(line)
  if e['id'] in seen:continue
  seen.add(e['id']);names[e['repo']['id']]=e['repo']['name']
  if e['type']=='PullRequestEvent':prs[(e['repo']['id'],e['payload']['number'])].append(e)
rows=collections.defaultdict(lambda:{'merged_prs':0,'durations':[]})
for (repo,num),events in prs.items():
 opened=[e['created_at'] for e in events if e['payload']['action']=='opened'];merged=[e['created_at'] for e in events if e['payload']['action']=='merged']
